<script setup>
import {ref,computed} from 'vue';import {store,api,cargar,hoy,estado,nombreCurso} from '../store';const form=ref(null),error=ref(''),buscar=ref(''),curso=ref(''),filtro=ref('');const tipos=['Tarea','Examen','Trabajo','Exposición'],prioridades=['Alta','Media','Baja'],estados=['Pendiente','En proceso','Completado'];const filtradas=computed(()=>store.tareas.filter(t=>t.nombre.toLowerCase().includes(buscar.value.toLowerCase())&&(!curso.value||t.curso===curso.value)&&(!filtro.value||estado(t)===filtro.value)));function nueva(t){if(!store.cursos.length){error.value='Primero registra un curso.';return}form.value=t?{...t}:{nombre:'',curso:store.cursos[0].id,tipo:'Tarea',fecha:hoy(),prioridad:'Media',estado:'Pendiente',descripcion:''};error.value=''}async function guardar(){try{const t=form.value;await api('/actividades'+(t.id?'/'+t.id:''),t.id?'PUT':'POST',t);form.value=null;await cargar();error.value=''}catch(e){error.value=e.message}}async function completar(t){try{await api('/actividades/'+t.id,'PUT',{...t,estado:t.estado==='Completado'?'Pendiente':'Completado'});await cargar()}catch(e){error.value=e.message}}async function eliminar(t){if(!confirm('¿Eliminar actividad?'))return;try{await api('/actividades/'+t.id,'DELETE');await cargar()}catch(e){error.value=e.message}}
</script><template><div class="d-flex justify-content-between mb-3"><h2>Actividades</h2><button class="btn btn-primary" @click="nueva()">+ Nueva actividad</button></div><div v-if="error" class="alert alert-danger">{{error}}</div><form v-if="form" class="card p-3 mb-3" @submit.prevent="guardar"><h5>{{form.id?'Editar actividad':'Nueva actividad'}}</h5><div class="row g-2"><label class="col-md-6">Título<input class="form-control" v-model.trim="form.nombre" required></label><label class="col-md-6">Curso<select class="form-select" v-model="form.curso" required><option v-for="c in store.cursos" :key="c.id" :value="c.id">{{c.nombre}}</option></select></label><label class="col-md-3">Tipo<select class="form-select" v-model="form.tipo"><option v-for="t in tipos">{{t}}</option></select></label><label class="col-md-3">Fecha<input class="form-control" type="date" v-model="form.fecha" required></label><label class="col-md-3">Prioridad<select class="form-select" v-model="form.prioridad"><option v-for="p in prioridades">{{p}}</option></select></label><label class="col-md-3">Estado<select class="form-select" v-model="form.estado"><option v-for="e in estados">{{e}}</option></select></label><label class="col-12">Descripción<textarea class="form-control" v-model="form.descripcion" rows="2"></textarea></label></div><div class="mt-3"><button class="btn btn-primary me-2">Guardar</button><button type="button" class="btn btn-outline-secondary" @click="form=null">Cancelar</button></div></form><div class="card p-3"><div class="row g-2 mb-3"><div class="col-md-4"><input class="form-control" placeholder="Buscar actividad" v-model="buscar"></div><div class="col-md-4"><select class="form-select" v-model="curso"><option value="">Todos los cursos</option><option v-for="c in store.cursos" :value="c.id">{{c.nombre}}</option></select></div><div class="col-md-4"><select class="form-select" v-model="filtro"><option value="">Todos los estados</option><option v-for="e in [...estados,'Vencida']">{{e}}</option></select></div></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Actividad</th><th>Curso</th><th>Fecha</th><th>Prioridad</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="t in filtradas" :key="t.id"><td><strong>{{t.nombre}}</strong><div class="small text-secondary">{{t.tipo}} · {{t.descripcion}}</div></td><td>{{nombreCurso(t.curso)}}</td><td>{{t.fecha}}</td><td>{{t.prioridad}}</td><td><span class="badge" :class="estado(t)==='Completado'?'text-bg-success':estado(t)==='Vencida'?'text-bg-danger':'text-bg-secondary'">{{estado(t)}}</span></td><td class="text-nowrap"><button class="btn btn-sm btn-outline-success me-1" @click="completar(t)">{{t.estado==='Completado'?'Reabrir':'Completar'}}</button><button class="btn btn-sm btn-outline-primary me-1" @click="nueva(t)">Editar</button><button class="btn btn-sm btn-outline-danger" @click="eliminar(t)">Eliminar</button></td></tr></tbody></table></div><p v-if="!filtradas.length">No hay actividades.</p></div></template>